{
  "name": "projecting/project",
  "description": "Projecting standalone Symfony application and reusable Symfony bundle",
  "type": "symfony-bundle",
  "license": "proprietary",
  "require": {
    "doctrine/collections": "^2.2",
    "doctrine/dbal": "^4.0",
    "doctrine/doctrine-bundle": "^2.13 || ^3.0",
    "doctrine/doctrine-migrations-bundle": "^4.0",
    "doctrine/migrations": "^3.6",
    "doctrine/orm": "^3.3",
    "easycorp/easyadmin-bundle": "^5.5",
    "ext-json": "*",
    "cruding/crud": "*@dev",
    "interfacing/interface": "*@dev",
    "moneyphp/money": "^4.6",
    "objecting/object": "*@dev",
    "open-telemetry/exporter-otlp": "^1.0",
    "open-telemetry/sdk": "^1.0",
    "php": "^8.4",
    "psr/log": "^3.0",
    "symfony/cache": "^8.1",
    "symfony/console": "^8.1",
    "symfony/form": "^8.1",
    "symfony/framework-bundle": "^8.1",
    "symfony/messenger": "^8.1",
    "symfony/rate-limiter": "^8.1",
    "symfony/runtime": "^8.1",
    "symfony/security-bundle": "^8.1",
    "symfony/serializer": "^8.1",
    "symfony/workflow": "^8.1",
    "symfony/yaml": "^8.1",
    "symfony/http-client": "^8.1",
    "nyholm/psr7": "^1.8",
    "viewing/view": "*@dev"
  },
  "autoload": {
    "psr-4": {
      "App\\Projecting\\": "src/"
    }
  },
  "require-dev": {
    "administering/administration": "*@dev",
    "phpunit/phpunit": "^10.5",
    "friendsofphp/php-cs-fixer": "^3.94",
    "phpstan/phpstan": "^2.1",
    "phpstan/phpstan-doctrine": "^2.0",
    "symfony/browser-kit": "^8.1",
    "symfony/css-selector": "^8.1",
    "symfony/dom-crawler": "^8.1"
  },
  "scripts": {
    "test": "phpunit --colors=always",
    "test:coverage": "@php -d memory_limit=-1 -d xdebug.mode=coverage vendor/bin/phpunit --coverage-text=var/coverage-summary.txt --path-coverage",
    "test:coverage:summary": "@php -d memory_limit=-1 -d xdebug.mode=coverage vendor/bin/phpunit --coverage-text=var/coverage-summary.txt",
    "test:object-identity": "phpunit --colors=always tests/Unit/Project/ProjectingObjectIdentityContractTest.php",
    "lint": "php bin/php-lint.php",
    "php-cs-fixer": "php-cs-fixer fix --dry-run --diff --verbose",
    "phpstan": "phpstan analyse -c phpstan.neon",
    "gating": "php .gating/bin/gating check --target=. --policy-root=.gating/.gating --severity-config=.gating/.gating/config/severity.yaml",
    "schema:validate": "php bin/console doctrine:schema:validate --skip-sync --env=test",
    "schema:parity": [
      "php bin/console doctrine:schema:validate --skip-sync --env=test --no-interaction",
      "php bin/console doctrine:migrations:up-to-date --env=test --no-interaction"
    ],
    "start:dev": "php -S 127.0.0.1:8080 -t public",
    "consume": "php -d variables_order=EGPCS -r \"passthru('php bin/console messenger:consume async -vv', $e); exit($e);\"",
    "retry-failed": "php -r \"passthru('php bin/console messenger:failed:retry --force', $e); exit($e);\""
  },
  "config": {
    "allow-plugins": {
      "symfony/runtime": true,
      "tbachert/spi": true,
      "php-http/discovery": true
    }
  },
  "repositories": [
    {
      "type": "path",
      "url": "../Administering",
      "options": {
        "symlink": true
      }
    },
    {
      "type": "path",
      "url": "../Objecting",
      "options": {
        "symlink": true
      }
    },
    {
      "type": "path",
      "url": "../Cruding",
      "options": {
        "symlink": true
      }
    },
    {
      "type": "path",
      "url": "../Viewing",
      "options": {
        "symlink": true
      }
    },
    {
      "type": "path",
      "url": "../Interfacing",
      "options": {
        "symlink": true
      }
    }
  ]
}
